function toggleAnalysisSettings(){let type=eventAnalysisType.value,levelField=document.getElementById('levelResultSettings'),propertyField=document.getElementById('propertyAnalysisSettings'),levelVisible=type==='level_result',propertyVisible=type==='property';levelField.style.display=levelVisible?'grid':'none';propertyField.style.display=propertyVisible?'grid':'none';if(levelVisible&&!eventModeRows.length){eventModeRows=[{id:'',display_name:'',fail_reasons:[]}];renderEventModes()}if(propertyVisible&&!eventPropertyRows.length){eventPropertyRows=[{key:'',description:'',type:'number',limit:20}];renderEventProperties()}if(levelVisible&&!eventKey.value.trim())eventKey.value='level_result';if(levelVisible&&!eventName.value.trim())eventName.value='关卡结果';if(levelVisible&&eventCategory.value==='custom')eventCategory.value='level'}
