function eventTableSettingsPayload(){let key=eventTableKey.value.trim(),name=eventTableName.value.trim(),field=eventTableField.value.trim();if(!key&&!name&&!field)return null;if(!/^[a-z][a-z0-9_]{0,63}$/.test(key))throw Error('表格标识只能使用小写字母、数字和下划线，且必须以字母开头');if(!name||name.length>128)throw Error('请填写不超过 128 个字符的表格名称');if(!field||field.length>128)throw Error('请填写不超过 128 个字符的本事件统计字段');let order=Number(eventTableOrder.value||0);if(!Number.isInteger(order)||order<0||order>10000)throw Error('显示顺序必须是 0-10000 之间的整数');return {key,name,field,order}}
function eventDefinitionPayload(){let analysisType=eventAnalysisType.value,settings={},table=eventTableSettingsPayload();if(analysisType==='property'){let fields=readEventProperties();if(!fields.length||fields.some(item=>!item.key||!item.description))throw Error('请完整填写每个属性字段和描述');if(fields.some(item=>!/^[A-Za-z_][A-Za-z0-9_]*(?:\.[A-Za-z_][A-Za-z0-9_]*){0,7}$/.test(item.key)||item.key.length>128))throw Error('属性字段必须是点号分隔的 JSON 字段路径，且不能超过 128 个字符');if(new Set(fields.map(item=>item.key)).size!==fields.length)throw Error('属性字段不能重复');if(fields.some(item=>!['number','dimension'].includes(item.type)))throw Error('属性数据类型无效');if(fields.some(item=>!Number.isInteger(item.limit)||item.limit<1||item.limit>100))throw Error('枚举显示数必须是 1-100 之间的整数');settings={fields}}if(analysisType==='level_result'){let modes=readEventModes();if(!modes.length||modes.some(item=>!item.id||!item.display_name))throw Error('请完整填写每个玩法的 mode_id 和显示名');if(modes.some(item=>!/^[a-z][a-z0-9_]{0,63}$/.test(item.id)))throw Error('mode_id 只能使用小写字母、数字和下划线，且必须以字母开头');if(new Set(modes.map(item=>item.id)).size!==modes.length)throw Error('玩法 mode_id 不能重复');if(modes.some(item=>item.fail_reasons.some(reason=>!/^[a-z][a-z0-9_]{0,63}$/.test(reason))))throw Error('失败原因只能使用小写字母、数字和下划线');let threshold=Number(eventStuckThreshold.value);if(!Number.isInteger(threshold)||threshold<1||threshold>100)throw Error('疑似卡关失败次数必须是 1-100 之间的整数');settings={suspected_stuck_failures:threshold,collection_started_at:eventCollectionStartedAt.value,modes}}if(table)settings.table=table;return {name:eventName.value.trim(),category:eventCategory.value.trim(),description:eventDescription.value.trim(),analysis_type:analysisType,settings}}
async function createEventDefinition(){try{await api(`/api/admin/games/${selected.id}/event-definitions`,{method:'POST',body:JSON.stringify({event_key:eventKey.value.trim(),...eventDefinitionPayload()})});closeModal();notify('运营打点已创建');showAnalytics(selected.id,analyticsDays)}catch(e){notify(e.message)}}
async function createEventDefinitionsBatch(){let input=document.getElementById('eventBatchJson'),button=document.getElementById('eventBatchCreateButton'),status=document.getElementById('eventBatchStatus');try{eventBatchDefinitions=applyEventBatchTable(parseEventDefinitionsJson(input?.value||''));renderEventBatchPreview();if(button){button.disabled=true;button.textContent='创建中…'}let result=await api(`/api/admin/games/${selected.id}/event-definitions/batch`,{method:'POST',body:JSON.stringify({definitions:eventBatchDefinitions})});closeModal();notify(`已批量创建 ${result.created} 个运营打点`);showAnalytics(selected.id,analyticsDays)}catch(e){if(button){button.disabled=false;button.textContent='批量创建'}if(status){status.className='event-json-status error';status.textContent=e.message}notify(e.message)}}
async function updateEventDefinition(id){try{await api(`/api/admin/event-definitions/${id}`,{method:'PATCH',body:JSON.stringify({...eventDefinitionPayload(),enabled:eventEnabled.checked})});closeModal();notify('打点设置已保存');showAnalytics(selected.id,analyticsDays)}catch(e){notify(e.message)}}
async function toggleEventDefinition(id,enabled){try{await api(`/api/admin/event-definitions/${id}`,{method:'PATCH',body:JSON.stringify({enabled})});notify(enabled?'打点已启用':'打点已停用');showAnalytics(selected.id,analyticsDays)}catch(e){notify(e.message)}}
async function deleteEventDefinition(id){if(!confirm('确认删除这个打点定义？已有历史数据的事件只能停用，不能删除。'))return;try{await api(`/api/admin/event-definitions/${id}`,{method:'DELETE'});notify('打点定义已删除');showAnalytics(selected.id,analyticsDays)}catch(e){notify(e.message)}}
async function openProjectSettings(){try{let s=selected.settings||{},wechat=await api(`/api/admin/games/${selected.id}/wechat-credentials`);dialog.innerHTML=`<h3>项目设置</h3><div class="field"><label>名称</label><input id="settingName" value="${esc(selected.name)}"></div><div class="field"><label>项目类型</label><select id="settingProjectType">${projectTypeOptions(selected.project_type||'game')}</select></div><div class="field"><label>说明</label><input id="settingDesc" value="${esc(selected.description||'')}"></div><div class="field"><label>API 错误率告警阈值（0-1）</label><input id="settingThreshold" type="number" min="0" max="1" step="0.01" value="${Number(s.error_rate_threshold||0.05)}"></div><div class="field"><label><input id="settingEnabled" type="checkbox" ${selected.enabled?'checked':''}> 启用项目</label></div><button class="btn" onclick="saveProjectSettings()">保存基础设置</button><hr style="margin:24px 0;border:0;border-top:1px solid #e4e9f0"><div class="row space"><h3 style="margin:0">微信 OpenID 登录</h3><span class="status-chip ${wechat.configured?'':'off'}"><i></i>${wechat.configured?'已配置':'未配置'}</span></div><p class="muted">AppID 和 AppSecret 按项目独立保存。AppSecret 加密存储，保存后不会再次显示。</p><div class="field"><label>微信 AppID</label><input id="wechatAppId" value="${esc(wechat.app_id||'')}" placeholder="例如：wx1234567890abcdef"></div><div class="field"><label>微信 AppSecret</label><input id="wechatAppSecret" type="password" autocomplete="new-password" placeholder="${wechat.configured?'留空则保留当前 AppSecret':'请输入 AppSecret'}"></div><div class="row"><button class="btn" onclick="saveWechatCredentials()">保存微信配置</button>${wechat.configured?'<button class="btn danger" onclick="removeWechatCredentials()">移除微信配置</button>':''}</div><p class="muted">只有项目所有者可以修改；小游戏端只发送 wx.login() 的临时 code。</p>`;modal.style.display='flex'}catch(e){notify(e.message)}}
async function saveProjectSettings(){try{let updated=await api(`/api/admin/games/${selected.id}`,{method:'PATCH',body:JSON.stringify({name:settingName.value,project_type:settingProjectType.value,description:settingDesc.value,enabled:settingEnabled.checked,settings:{...(selected.settings||{}),error_rate_threshold:Number(settingThreshold.value)}})});Object.assign(selected,updated);closeModal();notify('项目设置已保存');showProject(selected.id)}catch(e){notify(e.message)}}
async function saveWechatCredentials(){try{let payload={app_id:wechatAppId.value.trim()};if(wechatAppSecret.value)payload.app_secret=wechatAppSecret.value;await api(`/api/admin/games/${selected.id}/wechat-credentials`,{method:'PUT',body:JSON.stringify(payload)});notify('微信登录配置已保存');await openProjectSettings()}catch(e){notify(e.message)}}
async function removeWechatCredentials(){if(!confirm('确认移除该项目的微信登录配置？移除后新玩家将无法通过微信登录。'))return;try{await api(`/api/admin/games/${selected.id}/wechat-credentials`,{method:'DELETE'});notify('微信登录配置已移除');await openProjectSettings()}catch(e){notify(e.message)}}
function openNewKey(){dialog.innerHTML=`<h3>新建 API Key</h3><div class="field"><label>密钥名称</label><input id="keyName" placeholder="例如：正式服务端"></div><div class="field"><label>权限范围</label><label><input type="checkbox" name="keyScope" value="config:read" checked> 读取配置</label><label><input type="checkbox" name="keyScope" value="user:resolve"> 解析用户</label><label><input type="checkbox" name="keyScope" value="archive:read"> 读取存档</label><label><input type="checkbox" name="keyScope" value="archive:write"> 写入存档</label><label><input type="checkbox" name="keyScope" value="analytics:write"> 上报运营打点</label></div><button class="btn" onclick="createProjectKey()">创建密钥</button>`;modal.style.display='flex'}
async function createProjectKey(){try{let scopes=[...document.querySelectorAll('input[name=keyScope]:checked')].map(x=>x.value),x=await api(`/api/admin/games/${selected.id}/keys`,{method:'POST',body:JSON.stringify({name:keyName.value,scopes})});dialog.innerHTML=`<h3>密钥创建成功</h3><p>请立即保存，关闭后无法再次查看。</p><div id="apiKeyText" class="api-key-box">${esc(x.api_key)}</div><div class="row"><button class="btn" onclick="copyApiKey()">复制 API Key</button><button class="btn secondary" onclick="closeModal();showProject(selected.id)">已保存并关闭</button></div>`}catch(e){notify(e.message)}}
function keyScopeFields(scopes){let options=[['config:read','读取配置'],['user:resolve','解析用户'],['archive:read','读取存档'],['archive:write','写入存档'],['analytics:write','上报运营打点']];return options.map(([value,label])=>`<label><input type="checkbox" name="editKeyScope" value="${value}" ${scopes.includes(value)?'checked':''}> ${label}</label>`).join('')}
function openEditProjectKey(id){let key=projectKeys.find(x=>x.id===id);if(!key)return;dialog.innerHTML=`<h3>编辑 API Key</h3><div class="field"><label>密钥名称</label><input id="editKeyName" value="${esc(key.name)}"></div><div class="field"><label>权限范围</label>${keyScopeFields(key.scopes)}</div><p class="muted">修改权限立即生效；密钥内容本身不会改变。</p><div class="row"><button class="btn" onclick="saveProjectKey('${id}')">保存</button><button class="btn secondary" onclick="closeModal()">取消</button></div>`;modal.style.display='flex'}
async function saveProjectKey(id){try{let scopes=[...document.querySelectorAll('input[name=editKeyScope]:checked')].map(x=>x.value);await api('/api/admin/keys/'+id,{method:'PATCH',body:JSON.stringify({name:editKeyName.value,scopes})});closeModal();notify('密钥权限已更新');showProject(selected.id)}catch(e){notify(e.message)}}
async function toggleKey(id,enabled){try{await api('/api/admin/keys/'+id,{method:'PATCH',body:JSON.stringify({enabled})});notify(enabled?'密钥已启用':'密钥已停用');showProject(selected.id)}catch(e){notify(e.message)}}
async function exportConfigs(){let data=await api(`/api/admin/games/${selected.id}/configs/export`),blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`${selected.game_key}-configs.json`;a.click();URL.revokeObjectURL(a.href)}
function openImportConfigs(){dialog.innerHTML=`<h3>批量导入配置</h3><p class="muted">粘贴导出文件的完整 JSON，最多 500 项；同环境同配置键会更新。</p><textarea id="importValue">{"configs":[]}</textarea><button class="btn" onclick="importConfigs()">确认导入</button>`;modal.style.display='flex'}
async function importConfigs(){try{let value=JSON.parse(importValue.value),x=await api(`/api/admin/games/${selected.id}/configs/import`,{method:'POST',body:JSON.stringify({configs:value.configs||[]})});closeModal();notify(`已导入 ${x.imported} 项配置`);showProject(selected.id)}catch(e){notify(e.message)}}
